from pathlib import Path
import sys
from nwn.nwscript.comp import Compiler
from nwn.nwscript import langspec
from nwn.nwscript.vm import VM, Script

source = Path(sys.argv[1]).resolve()
spec = Path(sys.argv[2]).resolve()

def resolve(filename):
    name = Path(filename).name
    if name == source.name:
        return source.read_bytes()
    if name == "nwscript.nss":
        return spec.read_bytes()
    return None

compiler = Compiler(resolve)
bytecode, debug = compiler.compile(source.name)
source.with_suffix(".ncs").write_bytes(bytecode)
if isinstance(debug, bytes):
    source.with_suffix(".ndb").write_bytes(debug)
else:
    source.with_suffix(".ndb").write_text(debug)

class PrintHost:
    def PrintString(self, value: str) -> None:
        print(value)

script = Script.from_compiled(str(source.with_suffix("")))
with spec.open(encoding="latin-1") as stream:
    runtime = VM(script, langspec.read(stream), PrintHost())
runtime.run()
